const enc = new TextEncoder();
export const random = () => crypto.randomUUID();
export async function hash(value) {
  return [...new Uint8Array(await crypto.subtle.digest("SHA-256", enc.encode(value)))].map((x) => x.toString(16).padStart(2, "0")).join("");
}
export async function token(secret, kind, p) {
  const key = await crypto.subtle.importKey("raw", enc.encode(secret), { name: "HMAC", hash: "SHA-256" }, false, ["sign"]);
  return [...new Uint8Array(await crypto.subtle.sign("HMAC", key, enc.encode(`${kind}:${p.id}:${p.version}`)))].map((x) => x.toString(16).padStart(2, "0")).join("");
}
export function equal(a, b) {
  if (typeof a !== "string" || typeof b !== "string" || a.length !== b.length) return false;
  let diff = 0;
  for (let i = 0; i < a.length; i++) diff |= a.charCodeAt(i) ^ b.charCodeAt(i);
  return diff === 0;
}
export const escape = (value) => String(value ?? "").replace(/[&<>"']/g, (c) => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" })[c]);

/consent/app.js.content:
"use strict";

const AGREEMENT_VERSION = "2026-2027";
const WEB3FORMS_ACCESS_KEY = "558eb16e-8262-445d-8759-635dd9d2972d";
const SUBMISSION_ENDPOINT = "https://api.web3forms.com/submit";
const TOTAL_STEPS = 6;

const welcomeScreen = document.getElementById("welcomeScreen");
const formScreen = document.getElementById("formScreen");
const startButton = document.getElementById("startButton");
const form = document.getElementById("consentForm");
const stepCards = Array.from(document.querySelectorAll("[data-step]"));
const stepButtons = Array.from(document.querySelectorAll("[data-step-target]"));
const backButton = document.getElementById("backButton");
const nextButton = document.getElementById("nextButton");
const submitButton = document.getElementById("submitButton");
const submitLabel = submitButton.querySelector(".submit-label");
const progressText = document.getElementById("progressText");
const formAlert = document.getElementById("formAlert");
const progress = document.querySelector(".progress");
const successScreen = document.getElementById("successScreen");
const guardianGroup = document.getElementById("guardianGroup");
const participantDob = document.getElementById("participantDob");
const guardianName = document.getElementById("guardianName");
const guardianSignature = document.getElementById("guardianSignature");
const reviewList = document.getElementById("reviewList");

let currentStep = 0;
let maxUnlockedStep = 0;
const completedSteps = new Set();

const fieldRules = {
  participantName: {
    message: "Enter the participant's full legal name.",
    validate: (value) => value.trim().length >= 2
  },
  participantDob: {
    message: "Enter a valid date of birth that is not in the future.",
    validate: (value) => {
      const date = parseDateInput(value);
      return Boolean(date && date <= startOfToday() && date.getFullYear() >= 1900);
    }
  },
  contactEmail: {
    message: "Enter a valid email address.",
    validate: (value) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(value.trim())
  },
  contactPhone: {
    message: "Enter a phone number with at least 7 digits.",
    validate: (value) => value.replace(/\D/g, "").length >= 7
  },
  participantSignature: {
    message: "Type the participant's full legal name to sign.",
    validate: (value) => value.trim().length >= 2
  },
  guardianName: {
    message: "Enter the parent or guardian's full legal name.",
    validate: (value) => value.trim().length >= 2
  },
  guardianSignature: {
    message: "Type the parent or guardian's full legal name to sign.",
    validate: (value) => value.trim().length >= 2
  }
};

function parseDateInput(value) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(value || "")) return null;
  const [year, month, day] = value.split("-").map(Number);
  const date = new Date(year, month - 1, day);
  if (date.getFullYear() !== year || date.getMonth() !== month - 1 || date.getDate() !== day) return null;
  return date;
}

function startOfToday() {
  const now = new Date();
  return new Date(now.getFullYear(), now.getMonth(), now.getDate());
}

function formatDate(date) {
  return new Intl.DateTimeFormat("en-CA", {
    year: "numeric",
    month: "long",
    day: "numeric"
  }).format(date);
}

function participantAge() {
  const dob = parseDateInput(participantDob.value);
  if (!dob) return null;
  const today = startOfToday();
  let age = today.getFullYear() - dob.getFullYear();
  const monthDifference = today.getMonth() - dob.getMonth();
  if (monthDifference < 0 || (monthDifference === 0 && today.getDate() < dob.getDate())) age -= 1;
  return age;
}

function isMinor() {
  const age = participantAge();
  return age !== null && age < 18;
}

function setSignatureDates() {
  const signedDate = formatDate(startOfToday());
  document.getElementById("participantSignedDate").value = signedDate;
  document.getElementById("guardianSignedDate").value = signedDate;
}

function updateGuardianRequirement() {
  const minor = isMinor();
  guardianGroup.hidden = !minor;
  guardianName.required = minor;
  guardianSignature.required = minor;
  if (!minor) {
    clearFieldError(guardianName);
    clearFieldError(guardianSignature);
  }
}

function showAlert(message) {
  formAlert.textContent = message;
  formAlert.hidden = false;
}

function clearAlert() {
  formAlert.textContent = "";
  formAlert.hidden = true;
}

function errorElementFor(input) {
  return document.getElementById(`${input.id}Error`);
}

function setFieldError(input, message) {
  input.setAttribute("aria-invalid", "true");
  const error = errorElementFor(input);
  if (error) {
    error.textContent = message;
    input.setAttribute("aria-describedby", error.id);
  }
}

function clearFieldError(input) {
  input.removeAttribute("aria-invalid");
  input.removeAttribute("aria-describedby");
  const error = errorElementFor(input);
  if (error) error.textContent = "";
}

function validateField(id) {
  const input = document.getElementById(id);
  const rule = fieldRules[id];
  const valid = rule.validate(input.value || "");
  if (valid) clearFieldError(input);
  else setFieldError(input, rule.message);
  return valid;
}

function focusInvalid(element) {
  if (!element) return;
  const top = element.getBoundingClientRect().top + window.scrollY - 130;
  window.scrollTo({ top: Math.max(0, top), behavior: preferredScrollBehavior() });
  window.setTimeout(() => element.focus({ preventScroll: true }), 180);
}

function preferredScrollBehavior() {
  return window.matchMedia("(prefers-reduced-motion: reduce)").matches ? "auto" : "smooth";
}

function validateCheckbox(id, message) {
  const input = document.getElementById(id);
  if (input.checked) {
    input.removeAttribute("aria-invalid");
    return true;
  }
  input.setAttribute("aria-invalid", "true");
  showAlert(message);
  focusInvalid(input);
  return false;
}

function validateStep(step, options = {}) {
  const announce = options.announce !== false;
  clearAlert();
  let valid = true;
  let firstInvalid = null;

  const checkFields = (ids) => {
    ids.forEach((id) => {
      const input = document.getElementById(id);
      if (!validateField(id)) {
        valid = false;
        if (!firstInvalid) firstInvalid = input;
      }
    });
  };

  if (step === 0) {
    checkFields(["participantName", "participantDob", "contactEmail", "contactPhone"]);
  } else if (step === 1) {
    valid = validateCheckbox("ack12", "Please confirm that paragraphs 1 and 2 have been read and accepted.");
  } else if (step === 2) {
    valid = validateCheckbox("ack34", "Please confirm that paragraphs 3 and 4 have been read and accepted.");
  } else if (step === 3) {
    valid = validateCheckbox("ack57", "Please confirm that paragraphs 5 to 7 have been read and accepted.");
  } else if (step === 4) {
    checkFields(["participantSignature"]);
    if (isMinor()) checkFields(["guardianName", "guardianSignature"]);
    const consent = document.getElementById("electronicConsent");
    if (!consent.checked) {
      valid = false;
      consent.setAttribute("aria-invalid", "true");
      if (!firstInvalid) firstInvalid = consent;
    } else {
      consent.removeAttribute("aria-invalid");
    }
  } else if (step === 5) {
    const finalConfirmation = document.getElementById("finalConfirmation");
    if (!finalConfirmation.checked) {
      valid = false;
      finalConfirmation.setAttribute("aria-invalid", "true");
      firstInvalid = finalConfirmation;
    } else {
      finalConfirmation.removeAttribute("aria-invalid");
    }
  }

  if (!valid && announce && !formAlert.textContent) {
    showAlert(step === 4
      ? "Please complete the required signature fields and confirm the electronic-signature statement."
      : step === 5
        ? "Please confirm that the signed agreement is ready to submit."
        : "Please complete all required fields before continuing.");
  }

  if (!valid && announce && firstInvalid) focusInvalid(firstInvalid);
  return valid;
}

function updateProgress() {
  stepButtons.forEach((button, index) => {
    const active = index === currentStep;
    button.toggleAttribute("aria-current", active);
    if (active) button.setAttribute("aria-current", "step");
    button.disabled = index > maxUnlockedStep;
    button.dataset.complete = completedSteps.has(index) ? "true" : "false";
  });

  progressText.textContent = `Section ${currentStep + 1} of ${TOTAL_STEPS}`;
  backButton.textContent = currentStep === 0 ? "← Start" : "← Back";
  nextButton.hidden = currentStep === TOTAL_STEPS - 1;
  submitButton.hidden = currentStep !== TOTAL_STEPS - 1;

  const activeButton = stepButtons[currentStep];
  if (activeButton) {
    const targetLeft = activeButton.offsetLeft - (progress.clientWidth - activeButton.offsetWidth) / 2;
    progress.scrollTo({ left: Math.max(0, targetLeft), behavior: preferredScrollBehavior() });
  }
}

function showStep(step, options = {}) {
  currentStep = Math.max(0, Math.min(TOTAL_STEPS - 1, step));
  stepCards.forEach((card, index) => {
    card.hidden = index !== currentStep;
  });
  clearAlert();
  updateGuardianRequirement();
  if (currentStep === TOTAL_STEPS - 1) populateReview();
  updateProgress();

  const activeCard = stepCards[currentStep];
  const formTop = formScreen.getBoundingClientRect().top + window.scrollY;
  window.scrollTo({ top: Math.max(0, formTop), behavior: "auto" });
  if (options.focus !== false) {
    const heading = activeCard.querySelector("h2");
    window.setTimeout(() => heading?.focus({ preventScroll: true }), 180);
  }
}

function startForm() {
  welcomeScreen.hidden = true;
  formScreen.hidden = false;
  window.scrollTo({ top: 0, behavior: "auto" });
  showStep(0);
}

function returnToWelcome() {
  formScreen.hidden = true;
  welcomeScreen.hidden = false;
  window.scrollTo({ top: 0, behavior: preferredScrollBehavior() });
  window.setTimeout(() => startButton.focus({ preventScroll: true }), 180);
}

function addReviewRow(label, value) {
  const row = document.createElement("div");
  const term = document.createElement("dt");
  const description = document.createElement("dd");
  term.textContent = label;
  description.textContent = value || "Not provided";
  row.append(term, description);
  reviewList.append(row);
}

function populateReview() {
  reviewList.replaceChildren();
  const age = participantAge();
  addReviewRow("Participant", valueOf("participantName"));
  addReviewRow("Date of birth", formatInputDate(participantDob.value));
  addReviewRow("Age at signing", age === null ? "Not available" : String(age));
  addReviewRow("Program or class", valueOf("programClass") || "Not specified");
  addReviewRow("Contact email", valueOf("contactEmail"));
  addReviewRow("Contact phone", valueOf("contactPhone"));
  addReviewRow("Participant signature", valueOf("participantSignature"));
  if (isMinor()) addReviewRow("Parent or guardian", valueOf("guardianName"));
  addReviewRow("Date signed", valueOf("participantSignedDate"));
}

function valueOf(id) {
  return document.getElementById(id).value.trim();
}

function formatInputDate(value) {
  const date = parseDateInput(value);
  return date ? formatDate(date) : value;
}

function generateReference() {
  const values = new Uint32Array(2);
  window.crypto.getRandomValues(values);
  const token = Array.from(values, (value) => value.toString(36).toUpperCase()).join("").slice(0, 10);
  return `LGW-${token}`;
}

function buildSubmission(reference, submittedAt) {
  const age = participantAge();
  const participantName = valueOf("participantName");
  const guardianRequired = isMinor();
  const guardian = guardianRequired ? valueOf("guardianName") : "Not required - participant is 18 or older";
  const summary = [
    `Reference: ${reference}`,
    `Agreement version: ${AGREEMENT_VERSION}`,
    `Participant: ${participantName}`,
    `Date of birth: ${participantDob.value}`,
    `Age at signing: ${age}`,
    `Program or class: ${valueOf("programClass") || "Not specified"}`,
    `Contact email: ${valueOf("contactEmail")}`,
    `Contact phone: ${valueOf("contactPhone")}`,
    `Participant signature: ${valueOf("participantSignature")}`,
    `Parent or guardian: ${guardian}`,
    `Parent or guardian signature: ${guardianRequired ? valueOf("guardianSignature") : "Not required"}`,
    `Signed date: ${valueOf("participantSignedDate")}`,
    "Paragraphs 1 and 2 acknowledged: Yes",
    "Paragraphs 3 and 4 acknowledged: Yes",
    "Paragraphs 5 to 7 acknowledged: Yes",
    "Electronic signature consent: Confirmed",
    `Submitted: ${submittedAt.toISOString()}`,
    `Source: ${window.location.origin + window.location.pathname}`
  ].join("\n");

  return {
    access_key: WEB3FORMS_ACCESS_KEY,
    subject: `Signed Participant Consent - ${participantName} - ${AGREEMENT_VERSION}`,
    from_name: "Leap Gymnastics Participant Consent Form",
    email: valueOf("contactEmail"),
    replyto: valueOf("contactEmail"),
    message: summary,
    "Reference": reference,
    "Agreement Version": AGREEMENT_VERSION,
    "Participant Name": participantName,
    "Participant Date of Birth": participantDob.value,
    "Participant Age at Signing": String(age),
    "Program or Class": valueOf("programClass") || "Not specified",
    "Contact Email": valueOf("contactEmail"),
    "Contact Phone": valueOf("contactPhone"),
    "Participant Signature": valueOf("participantSignature"),
    "Parent or Guardian Name": guardian,
    "Parent or Guardian Signature": guardianRequired ? valueOf("guardianSignature") : "Not required",
    "Signature Date": valueOf("participantSignedDate"),
    "Acknowledged Paragraphs 1 and 2": "Yes",
    "Acknowledged Paragraphs 3 and 4": "Yes",
    "Acknowledged Paragraphs 5 to 7": "Yes",
    "Electronic Signature Consent": "Confirmed",
    "Submitted At": submittedAt.toISOString(),
    "Source URL": window.location.origin + window.location.pathname,
    botcheck: valueOf("botcheck")
  };
}

async function submitAgreement(event) {
  event.preventDefault();
  clearAlert();

  for (let step = 0; step < TOTAL_STEPS; step += 1) {
    if (!validateStep(step, { announce: false })) {
      maxUnlockedStep = Math.max(maxUnlockedStep, step);
      showStep(step, { focus: false });
      validateStep(step, { announce: true });
      return;
    }
  }

  if (valueOf("botcheck")) return;

  const reference = generateReference();
  const submittedAt = new Date();
  const payload = buildSubmission(reference, submittedAt);
  let partyPayload = null;
  if (birthdayPartyId) {
    if (!birthdayContext) { showAlert("We could not verify the party link. Please reopen the guest link shared by your host."); return; }
    if (isMinor() && (!valueOf("guardianName").trim() || !valueOf("guardianSignature").trim())) { showAlert("Each participating child's parent or legal guardian must complete and sign the waiver."); return; }
    partyPayload = Object.fromEntries(["participantName", "participantDob", "contactEmail", "contactPhone", "participantSignature", "guardianName", "guardianSignature"].map(key => [key, valueOf(key)]));
    for (const key of ["ack12", "ack34", "ack57", "electronicConsent", "finalConfirmation"]) partyPayload[key] = document.getElementById(key).checked;
    partyPayload.agreementVersion = AGREEMENT_VERSION;
    partyPayload.submissionId = birthdaySubmissionId;
    partyPayload.editKey=consentSecret;
    if(priorConsent)partyPayload.supersedes=priorConsent;
  }

  submitButton.disabled = true;
  submitButton.classList.add("is-loading");
  submitLabel.textContent = "Submitting securely...";

  const controller = new AbortController();
  const timeout = window.setTimeout(() => controller.abort(), 20000);

  try {
    const response = await fetch(partyPayload ? BIRTHDAY_API + "/api/waivers?party=" + encodeURIComponent(birthdayPartyId) : SUBMISSION_ENDPOINT, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        "Accept": "application/json",
        ...(partyPayload ? { Authorization: "Bearer " + birthdayGuestToken } : {})
      },
      body: JSON.stringify(partyPayload || payload),
      signal: controller.signal
    });

    const result = await response.json().catch(() => ({}));
    if (!response.ok || result.success !== true) {
      throw new Error(result.message || result?.body?.message || "Submission was not accepted.");
    }

    if(partyPayload){priorConsent=result.reference;try{localStorage.setItem(consentStorageKey,JSON.stringify({key:consentSecret,reference:priorConsent}));}catch{}}
    document.getElementById("successParticipant").textContent = valueOf("participantName");
    document.getElementById("successReference").textContent = result.reference || reference;
    document.getElementById("successDate").textContent = `${formatDate(submittedAt)} at ${submittedAt.toLocaleTimeString("en-CA", { hour: "numeric", minute: "2-digit" })}`;
    form.hidden = true;
    progress.hidden = true;
    clearAlert();
    successScreen.hidden = false;
    window.scrollTo({ top: 0, behavior: preferredScrollBehavior() });
    window.setTimeout(() => document.getElementById("successTitle").focus({ preventScroll: true }), 180);
  } catch (error) {
    const message = error?.name === "AbortError"
      ? "The submission timed out. Check your connection and try again. Your form has not been cleared."
      : "We could not confirm delivery. Please try again. Your form has not been cleared.";
    showAlert(message);
    focusInvalid(formAlert);
  } finally {
    window.clearTimeout(timeout);
    submitButton.disabled = false;
    submitButton.classList.remove("is-loading");
    submitLabel.textContent = "Sign & submit agreement";
  }
}

startButton.addEventListener("click", startForm);

nextButton.addEventListener("click", () => {
  if (!validateStep(currentStep)) return;
  completedSteps.add(currentStep);
  maxUnlockedStep = Math.max(maxUnlockedStep, currentStep + 1);
  showStep(currentStep + 1);
});

backButton.addEventListener("click", () => {
  if (currentStep === 0) returnToWelcome();
  else showStep(currentStep - 1);
});

stepButtons.forEach((button) => {
  button.addEventListener("click", () => {
    const target = Number(button.dataset.stepTarget);
    if (!button.disabled && target <= maxUnlockedStep) showStep(target);
  });
});

participantDob.addEventListener("input", updateGuardianRequirement);
participantDob.addEventListener("change", updateGuardianRequirement);

Object.keys(fieldRules).forEach((id) => {
  const input = document.getElementById(id);
  input.addEventListener("input", () => {
    if (input.hasAttribute("aria-invalid")) validateField(id);
  });
  input.addEventListener("blur", () => {
    if (input.required && input.value) validateField(id);
  });
});

["ack12", "ack34", "ack57", "electronicConsent", "finalConfirmation"].forEach((id) => {
  document.getElementById(id).addEventListener("change", (event) => {
    if (event.target.checked) {
      event.target.removeAttribute("aria-invalid");
      clearAlert();
    }
  });
});

form.addEventListener("submit", submitAgreement);
document.getElementById("printButton").addEventListener("click", () => window.print());

document.getElementById("currentYear").textContent = String(new Date().getFullYear());
participantDob.max = `${startOfToday().getFullYear()}-${String(startOfToday().getMonth() + 1).padStart(2, "0")}-${String(startOfToday().getDate()).padStart(2, "0")}`;
setSignatureDates();
updateGuardianRequirement();
updateProgress();


// A guest capability identifies the party but cannot read the host's private details.
const BIRTHDAY_API = location.origin;
const birthdayPartyId = new URLSearchParams(location.search).get("party");
const birthdayFragment = new URLSearchParams(location.hash.slice(1));
let savedGuestToken=""; try { savedGuestToken=sessionStorage.getItem("leap-guest:" + birthdayPartyId)||""; } catch {}
const birthdayGuestToken = birthdayFragment.get("guest") || savedGuestToken;
let birthdayContext = null;
let birthdaySubmissionId = crypto.randomUUID();
const consentStorageKey='leap-consent-draft:'+birthdayPartyId;
let consentSecret='',priorConsent='';
try{const saved=JSON.parse(localStorage.getItem(consentStorageKey)||'{}');consentSecret=saved.key||'';priorConsent=saved.reference||'';}catch{}
if(!/^[a-f0-9]{64}$/.test(consentSecret))consentSecret=Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('');
const saveConsent=document.createElement('button');saveConsent.type='button';saveConsent.className='button button--secondary';saveConsent.textContent='Save';submitButton.before(saveConsent);
const draftStatus=document.createElement('p');draftStatus.setAttribute('role','status');saveConsent.before(draftStatus);
const consentFields=['participantName','participantDob','contactEmail','contactPhone','participantSignature','guardianName','guardianSignature'];
async function consentDraftRequest(method='GET',data){
 const r=await fetch(BIRTHDAY_API+'/api/consent-draft?party='+encodeURIComponent(birthdayPartyId),{method,headers:{Authorization:'Bearer '+birthdayGuestToken,'Content-Type':'application/json','X-Draft-Key':consentSecret},body:data?JSON.stringify(data):undefined});
 const j=await r.json();if(!r.ok)throw Error(j.error||'Please try again.');return j;
}
saveConsent.onclick=async()=>{saveConsent.disabled=true;try{
 localStorage.setItem(consentStorageKey,JSON.stringify({key:consentSecret,reference:priorConsent}));
 await consentDraftRequest('POST',Object.fromEntries(consentFields.map(k=>[k,valueOf(k)])));
 draftStatus.textContent='Your progress is saved. Return using the same browser to continue. Leap will receive it only when you sign and submit.';
}catch(error){draftStatus.textContent='Your progress could not be saved. Please keep this page open and try again.';}finally{saveConsent.disabled=false;}};
const anotherChild=document.createElement('button');anotherChild.type='button';anotherChild.className='button button--secondary';anotherChild.textContent='Start a form for another child';saveConsent.after(anotherChild);
anotherChild.onclick=()=>{
 priorConsent='';birthdaySubmissionId=crypto.randomUUID();
 consentSecret=Array.from(crypto.getRandomValues(new Uint8Array(32)),x=>x.toString(16).padStart(2,'0')).join('');
 let persistent=true;try{localStorage.setItem(consentStorageKey,JSON.stringify({key:consentSecret}));}catch{persistent=false;}
 form.reset();if(birthdayContext)document.getElementById('programClass').value=birthdayContext.title;
 draftStatus.textContent=persistent?'':'Your browser cannot save your progress. Keep this page open until you submit the form.';
 clearAlert();updateGuardianRequirement();setSignatureDates();maxUnlockedStep=0;completedSteps.clear();showStep(0);
};
const editConsent=document.createElement('button');editConsent.type='button';editConsent.className='button button--secondary';editConsent.textContent='Update my submitted details';document.getElementById('printButton').after(editConsent);
editConsent.onclick=()=>{birthdaySubmissionId=crypto.randomUUID();successScreen.hidden=true;form.hidden=false;progress.hidden=false;for(const k of ['ack12','ack34','ack57','electronicConsent','finalConfirmation'])document.getElementById(k).checked=false;setSignatureDates();maxUnlockedStep=0;completedSteps.clear();showStep(0);};
if (birthdayFragment.has("guest")) {
  try { sessionStorage.setItem("leap-guest:" + birthdayPartyId, birthdayGuestToken); } catch {}
  // Keep the guest capability in the address so a copied link remains usable.
}
if (birthdayPartyId) {
  startButton.disabled = true;
  fetch(BIRTHDAY_API + "/api/guest?party=" + encodeURIComponent(birthdayPartyId), { headers: { Authorization: "Bearer " + birthdayGuestToken } })
    .then(async response => { const data = await response.json(); if (!response.ok) throw new Error(data.error || "Party link not available"); return data; })
    .then(data => {
      birthdayContext = data;
      consentDraftRequest().then(result=>{if(result.draft){for(const k of consentFields)if(result.draft.data[k]!==undefined)document.getElementById(k).value=result.draft.data[k];updateGuardianRequirement();priorConsent=result.draft.reference||priorConsent;draftStatus.textContent=result.draft.submitted?'These details have been submitted. To make a change, review and sign the form again.':'Your saved progress has been restored. Review your answers and sign before submitting.';}}).catch(()=>{});
      document.getElementById("programClass").value = data.title;
      document.getElementById("programClass").readOnly = true;
      const note = document.createElement("p"); note.textContent = data.title; startButton.before(note);
      startButton.disabled = false;
      const shareUrl = location.origin + location.pathname + location.search + '#guest=' + encodeURIComponent(birthdayGuestToken);
      const share = document.createElement('button');
      share.type = 'button'; share.textContent = 'Copy guest waiver link';
      startButton.after(share);
      const feedback = document.createElement('p'); feedback.setAttribute('role','status'); share.after(feedback);
      share.addEventListener('click', async () => {
        try { await navigator.clipboard.writeText(shareUrl); feedback.textContent = 'Link copied. You can send it to the other families attending this party.'; }
        catch { const field=document.createElement('input');field.readOnly=true;field.value=shareUrl;field.setAttribute('aria-label','Guest waiver link');feedback.replaceChildren(field);field.select(); }
      });
    })
    .catch(() => {
      const note = document.createElement("p"); note.textContent = "This link is incomplete or is no longer available. Please ask your party host to send the full guest waiver link from their booking email. If you still need help, email info@leapgymnastics.ca."; startButton.before(note);
    });
}

if(!birthdayPartyId){startButton.disabled=true;const p=document.createElement("p");p.textContent="Please use the guest waiver link shared by your party host.";startButton.before(p);}

/consent/styles.css.content:
:root {
  --purple: #3b1f86;
  --purple-2: #5535b6;
  --purple-3: #6a47cf;
  --blue: #78d8f5;
  --ice: #d9f7ff;
  --lavender: #eee8ff;
  --ink: #160b46;
  --text: #263f59;
  --muted: #52677b;
  --lime: #e5ff39;
  --lime-hover: #d8f42f;
  --warm: #ff8d4d;
  --danger: #a32f36;
  --danger-bg: #fff0f1;
  --line: rgba(59, 31, 134, 0.18);
  --line-strong: rgba(59, 31, 134, 0.34);
  --surface: rgba(255, 255, 255, 0.94);
  --shadow: 0 18px 54px rgba(22, 11, 70, 0.12);
  --radius: 18px;
  --content: min(900px, calc(100vw - 40px));
}

*,
*::before,
*::after {
  box-sizing: border-box;
}

html {
  min-height: 100%;
  scroll-behavior: smooth;
  background: var(--ice);
  -webkit-text-size-adjust: 100%;
}

body {
  min-width: 280px;
  min-height: 100vh;
  margin: 0;
  color: var(--text);
  background: linear-gradient(135deg, var(--ice) 0%, var(--lavender) 58%, #e2f9ff 100%);
  font-family: "Manrope", Arial, sans-serif;
  line-height: 1.6;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

button,
input,
textarea,
select {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: transparent;
}

a {
  color: var(--purple);
  text-underline-offset: 0.2em;
}

img {
  display: block;
  max-width: 100%;
}

[hidden] {
  display: none !important;
}

.skip-link {
  position: fixed;
  top: 12px;
  left: 12px;
  z-index: 100;
  padding: 10px 14px;
  border-radius: 8px;
  color: #fff;
  background: var(--ink);
  transform: translateY(-160%);
}

.skip-link:focus {
  transform: translateY(0);
}

h1,
h2,
h3 {
  color: var(--ink);
  font-family: "Bricolage Grotesque", "Manrope", Arial, sans-serif;
  text-wrap: balance;
}

.welcome {
  display: grid;
  min-height: 100vh;
  place-items: center;
  padding: clamp(28px, 6vw, 72px) 20px;
  color: #fff;
  background:
    radial-gradient(circle at 82% 18%, rgba(120, 216, 245, 0.36), transparent 28%),
    radial-gradient(circle at 18% 84%, rgba(229, 255, 57, 0.13), transparent 26%),
    linear-gradient(115deg, var(--purple) 0%, var(--purple-2) 58%, #4a65bc 140%);
}

.welcome__inner {
  width: min(760px, 100%);
  text-align: center;
}

.welcome__logo {
  width: min(330px, 78vw);
  margin: 0 auto 18px;
}

.eyebrow,
.section-kicker {
  margin: 0;
  color: var(--purple-2);
  font-size: 0.76rem;
  font-weight: 800;
  letter-spacing: 0.17em;
  text-transform: uppercase;
}

.welcome .eyebrow {
  color: var(--lime);
}

.welcome h1 {
  max-width: 740px;
  margin: 12px auto 18px;
  color: #fff;
  font-size: clamp(2.35rem, 7vw, 4.4rem);
  font-weight: 500;
  letter-spacing: -0.035em;
  line-height: 1.02;
}

.welcome__lead {
  max-width: 650px;
  margin: 0 auto;
  color: rgba(255, 255, 255, 0.9);
  font-size: clamp(1rem, 2.2vw, 1.16rem);
  line-height: 1.72;
  text-wrap: pretty;
}

.welcome__facts {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 10px;
  margin: 28px 0 30px;
}

.welcome__facts span {
  padding: 8px 13px;
  border: 1px solid rgba(255, 255, 255, 0.2);
  border-radius: 999px;
  color: rgba(255, 255, 255, 0.9);
  background: rgba(255, 255, 255, 0.08);
  font-size: 0.82rem;
  font-weight: 700;
}

.welcome__pdf {
  display: block;
  width: fit-content;
  margin: 18px auto 0;
  color: rgba(255, 255, 255, 0.86);
  font-size: 0.88rem;
}

.welcome__pdf:hover {
  color: #fff;
}

.button {
  display: inline-flex;
  min-height: 48px;
  align-items: center;
  justify-content: center;
  gap: 9px;
  padding: 12px 24px;
  border: 1px solid transparent;
  border-radius: 999px;
  cursor: pointer;
  font-weight: 800;
  line-height: 1.2;
  text-align: center;
  text-decoration: none;
  transition: transform 160ms ease, background-color 160ms ease, border-color 160ms ease, box-shadow 160ms ease;
}

.button:hover {
  transform: translateY(-1px);
}

.button:active {
  transform: translateY(0);
}

.button:disabled {
  cursor: wait;
  opacity: 0.66;
  transform: none;
}

.button--large {
  min-height: 54px;
  padding-inline: 34px;
  font-size: 1rem;
}

.button--primary {
  border-color: rgba(22, 11, 70, 0.14);
  color: var(--ink);
  background: var(--lime);
  box-shadow: 0 10px 22px rgba(22, 11, 70, 0.13);
}

.button--primary:hover {
  background: var(--lime-hover);
}

.button--secondary {
  border-color: var(--line-strong);
  color: var(--purple);
  background: rgba(255, 255, 255, 0.72);
}

.button--secondary:hover {
  border-color: var(--purple-2);
  color: var(--ink);
  background: var(--lavender);
}

.form-app {
  min-height: 100vh;
  padding: clamp(22px, 5vw, 46px) 0 50px;
}

.form-brand {
  display: grid;
  width: var(--content);
  grid-template-columns: 210px minmax(0, 1fr);
  align-items: center;
  gap: 24px;
  margin: 0 auto 26px;
  padding: 18px 24px;
  border-radius: 14px;
  color: #fff;
  background: linear-gradient(115deg, var(--purple) 0%, var(--purple-2) 64%, #566fc1 130%);
  box-shadow: var(--shadow);
}

.form-brand a {
  display: block;
  border-radius: 8px;
}

.form-brand img {
  width: 100%;
}

.form-brand p {
  margin: 0 0 4px;
  color: var(--lime);
  font-size: 0.73rem;
  font-weight: 800;
  letter-spacing: 0.13em;
  text-transform: uppercase;
}

.form-brand__title {
  margin: 0;
  color: #fff;
  font-family: "Bricolage Grotesque", "Manrope", Arial, sans-serif;
  font-size: clamp(1.35rem, 3vw, 2rem);
  font-weight: 500;
  letter-spacing: normal;
  line-height: 1.15;
  text-transform: none;
  text-wrap: balance;
}

.progress {
  width: var(--content);
  margin: 0 auto 22px;
  overflow-x: auto;
  scrollbar-width: none;
}

.progress::-webkit-scrollbar {
  display: none;
}

.progress ol {
  display: flex;
  width: max-content;
  min-width: 100%;
  justify-content: center;
  gap: 7px;
  margin: 0;
  padding: 2px;
  list-style: none;
}

.progress button {
  display: flex;
  min-height: 44px;
  align-items: center;
  gap: 7px;
  padding: 8px 13px;
  border: 1px solid var(--line);
  border-radius: 999px;
  color: var(--muted);
  background: rgba(255, 255, 255, 0.72);
  cursor: pointer;
  font-size: 0.78rem;
  font-weight: 800;
  white-space: nowrap;
}

.progress button span {
  color: var(--purple-2);
  font-size: 0.7rem;
  font-variant-numeric: tabular-nums;
  opacity: 0.8;
}

.progress button[aria-current="step"] {
  border-color: var(--purple-2);
  color: var(--ink);
  background: var(--lavender);
}

.progress button[data-complete="true"] {
  border-color: rgba(59, 31, 134, 0.27);
  color: var(--purple);
  background: rgba(217, 247, 255, 0.9);
}

.progress button:disabled {
  cursor: not-allowed;
  opacity: 0.56;
}

.form-alert {
  width: var(--content);
  margin: 0 auto 18px;
  padding: 13px 16px;
  border: 1px solid rgba(163, 47, 54, 0.38);
  border-radius: 10px;
  color: #76252b;
  background: var(--danger-bg);
  font-size: 0.92rem;
  font-weight: 700;
}

.step-card,
.success-card {
  width: var(--content);
  margin: 0 auto;
  padding: clamp(26px, 5vw, 46px);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  color: var(--text);
  background: var(--surface);
  box-shadow: var(--shadow);
}

.step-card h2,
.success-card h2 {
  margin: 8px 0 10px;
  font-size: clamp(1.8rem, 4.6vw, 2.55rem);
  font-weight: 500;
  letter-spacing: -0.025em;
  line-height: 1.08;
}

.step-card h2:focus,
.success-card h2:focus {
  outline: none;
}

.section-intro {
  max-width: 70ch;
  margin: 0 0 28px;
  color: var(--muted);
  line-height: 1.72;
}

.field-grid {
  display: grid;
  grid-template-columns: repeat(2, minmax(0, 1fr));
  gap: 22px;
}

.field--wide {
  grid-column: 1 / -1;
}

.field label {
  display: block;
  margin: 0 0 8px;
  color: var(--ink);
  font-weight: 800;
}

.field label > span:not(.optional) {
  color: var(--danger);
}

.optional {
  display: inline-block;
  margin-left: 6px;
  color: var(--muted);
  font-size: 0.72rem;
  font-weight: 700;
  letter-spacing: 0.05em;
  text-transform: uppercase;
}

.field input,
.field textarea,
.field select {
  width: 100%;
  min-height: 50px;
  padding: 12px 14px;
  border: 1px solid rgba(59, 31, 134, 0.27);
  border-radius: 10px;
  color: var(--ink);
  background: #fff;
  box-shadow: none;
}

.field input::placeholder {
  color: #667a8e;
  opacity: 1;
}

.field input[readonly] {
  color: var(--muted);
  background: #f5f3fb;
}

.field input[aria-invalid="true"] {
  border-color: var(--danger);
  box-shadow: 0 0 0 3px rgba(163, 47, 54, 0.11);
}

.field-error {
  min-height: 0;
  margin: 6px 0 0;
  color: var(--danger);
  font-size: 0.8rem;
  font-weight: 700;
}

.field-error:empty {
  display: none;
}

.privacy-note {
  margin-top: 26px;
  padding: 16px 18px;
  border: 1px solid rgba(85, 53, 182, 0.2);
  border-radius: 12px;
  color: var(--text);
  background: #f7f5ff;
}

.privacy-note strong {
  color: var(--ink);
}

.privacy-note p {
  margin: 4px 0 0;
  font-size: 0.88rem;
}

.warning-banner {
  margin: 22px 0 24px;
  padding: 15px 17px;
  border-left: 4px solid var(--warm);
  border-radius: 0 10px 10px 0;
  color: var(--ink);
  background: #fff4ec;
}

.legal-copy {
  color: #253b52;
  font-size: 0.95rem;
  line-height: 1.72;
}

.legal-copy h3 {
  margin: 28px 0 8px;
  font-size: 1.28rem;
}

.legal-list,
.legal-sublist {
  padding-left: 1.55rem;
}

.legal-list {
  margin: 0;
}

.legal-list > li {
  padding-left: 0.35rem;
  margin-bottom: 20px;
}

.legal-list > li::marker {
  color: var(--purple-2);
  font-weight: 800;
}

.legal-sublist {
  margin: 9px 0 0;
}

.legal-sublist > li {
  padding-left: 0.25rem;
  margin-bottom: 5px;
}

.acknowledgement,
.consent-box {
  display: grid;
  grid-template-columns: 23px minmax(0, 1fr);
  align-items: start;
  gap: 13px;
  margin-top: 26px;
  padding: 16px 18px;
  border: 1px solid var(--line-strong);
  border-radius: 12px;
  color: var(--text);
  background: #fff;
  cursor: pointer;
}

.acknowledgement:hover,
.consent-box:hover {
  border-color: var(--purple-2);
  background: #faf9ff;
}

.acknowledgement:has(input:checked),
.consent-box:has(input:checked) {
  border-color: var(--purple-2);
  background: var(--lavender);
}

.acknowledgement input,
.consent-box input {
  width: 21px;
  height: 21px;
  margin: 2px 0 0;
  accent-color: var(--purple-2);
}

.acknowledgement span,
.consent-box span {
  min-width: 0;
}

.acknowledgement strong,
.consent-box strong {
  color: var(--ink);
}

.acknowledgement small {
  display: block;
  margin-top: 3px;
  color: var(--purple-2);
  font-size: 0.7rem;
  font-weight: 800;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.signature-group {
  margin: 24px 0 0;
  padding: 24px;
  border: 1px solid var(--line);
  border-radius: 14px;
  background: #fff;
}

.signature-group legend {
  padding: 0 8px;
  color: var(--ink);
  font-family: "Bricolage Grotesque", "Manrope", Arial, sans-serif;
  font-size: 1.25rem;
  font-weight: 700;
}

.signature-field input {
  font-family: "Bricolage Grotesque", "Manrope", Arial, sans-serif;
  font-size: 1.1rem;
  font-style: italic;
}

.minor-notice {
  display: flex;
  align-items: center;
  gap: 9px;
  margin: 0 0 20px;
  color: var(--purple);
  font-size: 0.86rem;
  font-weight: 800;
}

.minor-notice > span {
  width: 9px;
  height: 9px;
  flex: none;
  border-radius: 50%;
  background: var(--purple-3);
  box-shadow: 0 0 0 5px rgba(85, 53, 182, 0.12);
}

.review-list,
.success-details {
  display: grid;
  margin: 24px 0;
  border: 1px solid var(--line);
  border-radius: 14px;
  overflow: hidden;
  background: #fff;
}

.review-list > div,
.success-details > div {
  display: grid;
  grid-template-columns: minmax(145px, 0.42fr) minmax(0, 1fr);
  gap: 18px;
  padding: 13px 16px;
  border-bottom: 1px solid var(--line);
}

.review-list > div:last-child,
.success-details > div:last-child {
  border-bottom: 0;
}

.review-list dt,
.success-details dt {
  color: var(--muted);
  font-size: 0.78rem;
  font-weight: 800;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.review-list dd,
.success-details dd {
  min-width: 0;
  margin: 0;
  color: var(--ink);
  font-weight: 700;
  overflow-wrap: anywhere;
}

.review-agreement {
  padding: 20px 22px;
  border-radius: 14px;
  color: var(--text);
  background: #f7f5ff;
}

.review-agreement h3 {
  margin: 0 0 10px;
  font-size: 1.2rem;
}

.review-agreement ul {
  margin: 0;
  padding-left: 1.25rem;
}

.review-agreement li {
  margin-bottom: 5px;
}

.consent-box--final {
  border-width: 2px;
}

.bot-field {
  position: absolute;
  left: -10000px;
  width: 1px;
  height: 1px;
  overflow: hidden;
}

.form-actions {
  display: grid;
  width: var(--content);
  grid-template-columns: 1fr auto 1fr;
  align-items: center;
  gap: 16px;
  margin: 24px auto 0;
}

.form-actions .button:first-child {
  justify-self: start;
}

.form-actions .button:last-child,
.form-actions .submit-button {
  justify-self: end;
}

.form-actions p {
  margin: 0;
  color: var(--muted);
  font-size: 0.82rem;
  font-weight: 800;
  white-space: nowrap;
}

.spinner {
  display: none;
  width: 18px;
  height: 18px;
  border: 2px solid rgba(22, 11, 70, 0.25);
  border-top-color: var(--ink);
  border-radius: 50%;
  animation: spin 700ms linear infinite;
}

.submit-button.is-loading .spinner {
  display: block;
}

@keyframes spin {
  to { transform: rotate(360deg); }
}

.success-card {
  text-align: center;
}

.success-mark {
  display: grid;
  width: 68px;
  height: 68px;
  margin: 0 auto 18px;
  place-items: center;
  border: 2px solid var(--purple-2);
  border-radius: 50%;
  color: var(--purple-2);
  background: var(--lavender);
  font-size: 2rem;
  font-weight: 800;
}

.success-card > p:not(.section-kicker) {
  max-width: 620px;
  margin: 0 auto;
  color: var(--muted);
}

.success-details {
  max-width: 620px;
  margin-inline: auto;
  text-align: left;
}

.success-actions {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 12px;
}

.site-footer {
  display: grid;
  width: var(--content);
  grid-template-columns: 1fr auto;
  gap: 14px 26px;
  margin: 34px auto 0;
  padding: 24px 4px 0;
  border-top: 1px solid var(--line);
  color: var(--muted);
  font-size: 0.82rem;
}

.site-footer > div {
  display: flex;
  flex-direction: column;
}

.site-footer > div:nth-child(2) {
  text-align: right;
}

.site-footer strong {
  color: var(--ink);
}

.site-footer a {
  font-weight: 700;
}

.site-footer p {
  grid-column: 1 / -1;
  margin: 0;
}

button:focus-visible,
input:focus-visible,
a:focus-visible {
  outline: 3px solid var(--lime);
  outline-offset: 3px;
}

.field input:focus-visible {
  border-color: var(--purple-2);
  box-shadow: 0 0 0 3px rgba(85, 53, 182, 0.16);
  outline-color: transparent;
}

@media (max-width: 760px) {
  :root {
    --content: min(100% - 24px, 900px);
  }

  .welcome {
    padding-inline: 16px;
  }

  .welcome__facts {
    margin-block: 22px 26px;
  }

  .form-app {
    padding-top: 18px;
  }

  .form-brand {
    grid-template-columns: 150px minmax(0, 1fr);
    gap: 15px;
    padding: 15px 17px;
  }

  .progress ol {
    justify-content: flex-start;
  }

  .step-card,
  .success-card {
    padding: 25px 20px;
    border-radius: 14px;
  }

  .field-grid {
    grid-template-columns: 1fr;
    gap: 19px;
  }

  .field--wide {
    grid-column: auto;
  }

  .field input,
  .field textarea,
  .field select {
    font-size: 16px;
  }

  .signature-group {
    padding: 20px 16px;
  }

  .form-actions {
    grid-template-columns: 1fr 1fr;
    gap: 12px;
  }

  .form-actions p {
    grid-column: 1 / -1;
    grid-row: 1;
    justify-self: center;
  }

  .form-actions .button:first-child {
    grid-column: 1;
    grid-row: 2;
  }

  .form-actions .button:last-child,
  .form-actions .submit-button {
    grid-column: 2;
    grid-row: 2;
  }

  .site-footer {
    grid-template-columns: 1fr;
  }

  .site-footer > div:nth-child(2) {
    text-align: left;
  }
}

@media (max-width: 470px) {
  .welcome h1 {
    font-size: clamp(2.05rem, 12vw, 2.9rem);
  }

  .welcome__facts {
    gap: 7px;
  }

  .welcome__facts span {
    padding: 7px 10px;
    font-size: 0.74rem;
  }

  .form-brand {
    grid-template-columns: 1fr;
    text-align: center;
  }

  .form-brand a {
    width: 170px;
    margin: 0 auto;
  }

  .legal-copy {
    font-size: 0.9rem;
  }

  .legal-list,
  .legal-sublist {
    padding-left: 1.25rem;
  }

  .acknowledgement,
  .consent-box {
    grid-template-columns: 22px minmax(0, 1fr);
    padding: 14px;
  }

  .review-list > div,
  .success-details > div {
    grid-template-columns: 1fr;
    gap: 3px;
  }

  .form-actions .button {
    width: 100%;
    padding-inline: 16px;
  }
}

@media (prefers-reduced-motion: reduce) {
  html {
    scroll-behavior: auto;
  }

  *,
  *::before,
  *::after {
    animation-duration: 0.01ms !important;
    animation-iteration-count: 1 !important;
    transition-duration: 0.01ms !important;
  }
}

@media print {
  @page {
    margin: 0.55in;
  }

  body {
    color: #111;
    background: #fff;
  }

  .skip-link,
  .welcome,
  .progress,
  .form-alert,
  .form-actions,
  .success-actions {
    display: none !important;
  }

  .form-app,
  .success-card,
  .site-footer {
    display: block !important;
  }

  .form-app {
    padding: 0;
  }

  .form-brand,
  .step-card,
  .success-card {
    width: 100%;
    box-shadow: none;
  }

  .form-brand {
    margin-bottom: 18px;
    -webkit-print-color-adjust: exact;
    print-color-adjust: exact;
  }

  .step-card {
    display: block !important;
    margin: 0 0 16px;
    padding: 22px;
    break-inside: avoid;
  }

  .legal-card {
    break-inside: auto;
  }

  .legal-copy,
  .legal-list > li,
  .signature-group,
  .acknowledgement {
    break-inside: avoid;
  }

  .success-card[hidden] {
    display: none !important;
  }

  .site-footer {
    width: 100%;
  }
}

/billing.js.content:
import {packageConfig,torontoTime} from './domain.js';
import {escape as e} from './security.js';
export const POLICY = 'invoice-day-before-v1-draft';
export const CANCELLATION_COPY = 'If your invoice remains unpaid after the due date, your party booking may be cancelled.';
export const PAYMENT_COPY = 'Please book at least seven days in advance and choose your date and package at checkout. A $100 deposit plus HST ($113) is required to reserve your party and is applied toward the total cost.';
export const FORM_PAYMENT_COPY = 'Complete your party-details form at least seven days before your party. Your remaining balance will be shown before you submit. Once you submit the form, an itemized invoice will automatically be emailed to you, including HST and selected add-ons, with your deposit deducted.';
export const TRANSFER_COPY = 'Payment must be received by e-transfer to <a href="mailto:info@leapgymnastics.ca">info@leapgymnastics.ca</a> no later than the day before your party. Please include your invoice number in the transfer message. ' + CANCELLATION_COPY;
export const LATE_COPY = 'Late-departure fees, if any, are paid separately by e-transfer at the end of the party.';
export const PAYMENT_ACK = 'I understand that payment is due the day before my party and that my booking may be cancelled if payment is overdue.';
export const policyFor = p => JSON.parse(p.extras || '{}').booking?.billing?.policy === POLICY;
export const money = cents => new Intl.NumberFormat('en-CA',{style:'currency',currency:'CAD'}).format(cents/100);
const dateOnly = ms => new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'}).format(ms);
export function dueDate(p) {
  const date = new Date(dateOnly(p.start_at)+'T12:00:00Z');
  date.setUTCDate(date.getUTCDate()-1);
  return date.toISOString().slice(0,10);
}
export const dueLabel = p => new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',weekday:'long',month:'long',day:'numeric',year:'numeric'}).format(torontoTime(dueDate(p),'12:00 PM'));
export const policyText = p => `Please pay by ${dueLabel(p)}, the day before your party. ${CANCELLATION_COPY}`;
export function quote(p,details) {
  const c=packageConfig(p),b=JSON.parse(p.extras||'{}').booking?.billing;
  if(!policyFor(p)) throw Error('Existing booking: keep its agreed payment terms.');
  if(!c?.newPolicy) throw Error('This package needs a billing review.');
  const n=Number(details.children),bags=Number(details.loot||0);
  if(!Number.isInteger(n)||n<1||n>c.maxChildren) throw Error('Enter the number of participating children to see your total.');
  if(!Number.isInteger(bags)||bags<0||bags>22||(p.package==='Deluxe'&&bags)) throw Error('Please check the Mini Party Favour Bag quantity.');
  if(details.beverages && p.package!=='Premium') throw Error('Please check the drink station selection.');
  if(details.extraMinutes || details.theme || details.themed) throw Error('An existing special arrangement needs a billing review.');
  if(!Number.isSafeInteger(b?.depositCents)||b.depositCents<0||!b.depositReference) throw Error('Leap needs to verify the deposit before issuing the invoice.');
  if(b.discountReview || b.adjustmentReview) throw Error('Leap needs to check the booking adjustment before issuing the invoice.');
  const lines=[{key:'package',description:`${p.package} birthday package`,quantity:1,rateCents:Math.round(c.price*100)}];
  if(n>c.included) lines.push({key:'children',description:'Additional participating children',quantity:n-c.included,rateCents:Math.round(c.extraChild*100)});
  if(bags) lines.push({key:'favours',description:'Mini Party Favour Bags',quantity:bags,rateCents:700});
  if(details.beverages) lines.push({key:'drinks',description:'Cold Drink Station',quantity:1,rateCents:4000});
  for(const line of lines) line.amountCents=line.quantity*line.rateCents;
  const subtotalCents=lines.reduce((n,l)=>n+l.amountCents,0),taxCents=Math.round(subtotalCents*13/100),totalCents=subtotalCents+taxCents;
  if(b.depositCents>totalCents) throw Error('Leap needs to review the payment credit.');
  return {currency:'CAD',lines,subtotalCents,taxCents,totalCents,depositCents:b.depositCents,balanceCents:totalCents-b.depositCents,dueDate:dueDate(p),dueLabel:dueLabel(p),policy:POLICY};
}
export function quoteHtml(q) {
  return `<table class="invoice-lines"><caption>Invoice summary</caption><thead><tr><th scope="col">Description</th><th scope="col">Amount</th></tr></thead><tbody>${q.lines.map(l=>`<tr><td>${e(l.description)}${l.quantity>1?` (${l.quantity} at ${money(l.rateCents)})`:''}</td><td>${money(l.amountCents)}</td></tr>`).join('')}<tr><td>Subtotal</td><td>${money(q.subtotalCents)}</td></tr><tr><td>HST (13%)</td><td>${money(q.taxCents)}</td></tr><tr><td>Total including HST</td><td>${money(q.totalCents)}</td></tr><tr><td>Deposit paid (including HST)</td><td>-${money(q.depositCents)}</td></tr><tr class="balance"><th scope="row">Remaining balance</th><td>${money(q.balanceCents)}</td></tr></tbody></table><p><strong>Payment due: ${e(q.dueLabel)}</strong></p>`;
}
export function formBillingHtml(p) {
  return `<section id="party-payment"><h2>Deposit &amp; Payment</h2><p>${e(PAYMENT_COPY)}</p><p>${e(FORM_PAYMENT_COPY)}</p><p>${TRANSFER_COPY}</p><div id="billingSummary" aria-live="polite"></div></section>`;
}
export function agreementFor(p,agreements) {
  return policyFor(p)?[...agreements,{key:'paymentTerms',text:PAYMENT_ACK}]:agreements;
}
// This is an exception flag, not an automatic cancellation action.
export function cancellationReview(p,billing,now) {
  const partyDayStart=torontoTime(dateOnly(p.start_at),'12:00 AM');
  if(!policyFor(p)||p.status!=='active'||now<partyDayStart) return 'none';
  if(!billing?.deliveredAt||!billing.checkedAt||now-billing.checkedAt>5*60000||billing.transferPending||!Number.isSafeInteger(billing.balanceCents)||billing.balanceCents<0) return 'verify_payment';
  return billing.balanceCents===0?'paid':'confirm_cancellation';
}

/birthday-display.js.content:
// Payment ends with the invoice and e-transfer. Keep the existing custom CMS
// payment paragraphs consistent without changing links or any booking terms.
(function(){
 function paymentCopy(){
  document.querySelectorAll('p').forEach(function(p){
   var walk=document.createTreeWalker(p,NodeFilter.SHOW_TEXT),node;
   while((node=walk.nextNode()))if(node.nodeValue.indexOf('A receipt will be emailed once payment is confirmed.')!==-1)node.nodeValue=node.nodeValue.replace('A receipt will be emailed once payment is confirmed. ','').replace('A receipt will be emailed once payment is confirmed.','');
  });
 }
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',paymentCopy,{once:true});else paymentCopy();
})();
(function(){
'use strict';
if(!/^\/registration\/product-detail\/BDAY-(2026-(10|11|12)|2027-0[1-6])\/?$/.test(window.location.pathname))return;
function update(){
var cell=Array.from(document.querySelectorAll('td[colspan="2"]')).find(function(td){return /^Description:/.test(td.textContent.trim());});
if(!cell)return;
var paragraphs=Array.from(cell.querySelectorAll('p'));
paragraphs.forEach(function(p){var text=p.textContent.trim();
if(text.indexOf('Choose your party date and package, then pay')===0){p.innerHTML=p.innerHTML.replace('reserve your two-hour party','reserve your party');}
else if(text.indexOf('Basic: $350')===0){p.textContent='New bookings: Basic $399 + HST (10 children, 1 hour 45 minutes), Premium $589 + HST (16 children, 2 hours), or Deluxe $849 + HST (22 children, 2 hours 15 minutes). Counts include the birthday child. Basic additional children are $25 each above 10, maximum 16 total; Premium additional children are $25 each above 16, maximum 22 total. Deluxe includes up to 22; additional children are not available. Existing bookings retain their confirmed price, inclusions and party time.';}
else if(text.indexOf('Deluxe includes a cheerful balloon bouquet')===0){p.innerHTML='<a href="/birthday-parties/#party-packages">Compare all package inclusions and available extras</a>.';}
else if(text.indexOf("Kids' Drink Station")===0){p.textContent='Cold Drink Station: A selection of juice, soft drinks and bottled water for children and adults. Selection varies based on availability. Included with Deluxe; + $40 with Premium; unavailable with Basic.';var next=p.nextElementSibling;if(next && next.tagName==='UL')next.remove();}
else if(text.indexOf('(Offerings vary based on current availability)')===0)p.remove();
else if(text.indexOf('We no longer offer themed upgrades or additional party time.')===0){p.innerHTML=p.innerHTML.replace('We no longer offer themed upgrades or additional party time. ','');}
});
Array.from(document.querySelectorAll('tr')).forEach(function(row){var cells=row.querySelectorAll('th,td');if(cells.length!==2)return;var label=cells[0].textContent.trim();if(label.indexOf('Day / Time:')!==-1)cells[1].textContent='New bookings: Saturdays and Sundays beginning at 1:30 p.m. Basic finishes at 3:15 p.m., Premium at 3:30 p.m. and Deluxe at 3:45 p.m. Existing bookings retain their confirmed times.' + (/BDAY-2026-11\/?$/.test(location.pathname) ? ' Additional November 21 slot at 3:30 p.m.: Basic ends at 5:15 p.m., Premium at 5:30 p.m. and Deluxe at 5:45 p.m.' : '');if(label.indexOf('Drop In:')!==-1){var labelNode=cells[0].querySelector(".icon-dropin")||cells[0];var nodes=Array.from(labelNode.childNodes);nodes.forEach(function(n){if(n.nodeType===3)n.textContent=n.textContent.replace('Drop In:','Availability:');});}});
}

function updateModal(){
var modal=document.getElementById('editOrderItemModal');if(!modal||!modal.offsetHeight||!modal.querySelector('h2')||modal.querySelector('h2').textContent.indexOf('Birthday Parties')!==0)return false;
modal.querySelectorAll('li.tab .title').forEach(function(label){if(label.textContent.trim()==='Drop In')label.textContent='Availability / Book';});
var time=modal.querySelector('[title="Time"]');if(time)time.textContent='New bookings begin at 1:30 p.m. Basic finishes at 3:15 p.m., Premium at 3:30 p.m., Deluxe at 3:45 p.m. Existing bookings retain confirmed times.' + (/BDAY-2026-11\/?$/.test(location.pathname) ? ' Additional November 21 slot at 3:30 p.m.: Basic ends at 5:15 p.m., Premium at 5:30 p.m. and Deluxe at 5:45 p.m.' : '');
modal.querySelectorAll('.checkboxField.canRegister').forEach(function(row){var start=row.querySelector('[data-bind="text: event_start_time.date(TIME_ONLY)"]');var end=row.querySelector('[data-bind="text: event_end_time.date(TIME_ONLY)"]');if(start&&end&&!row.dataset.leapPartyTime){start.textContent=start.textContent+' start';end.hidden=true;if(end.previousSibling&&end.previousSibling.nodeType===3)end.previousSibling.textContent='';row.dataset.leapPartyTime='1';}});
return !!modal.querySelector('.checkboxField');
}
document.addEventListener('click',function(event){if(!event.target.closest('form.addToCartAjax'))return;var observer=new MutationObserver(function(){if(updateModal())observer.disconnect();});observer.observe(document.body,{childList:true,subtree:true});setTimeout(function(){observer.disconnect();},10000);});
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',update,{once:true});else update();
})();

/* Custom live birthday dates, October 6 2026 */
function leapBirthdayAvailabilityInit() {
  'use strict';
  var root = document.querySelector('[data-leap-party-availability]');
  if (!root || root._leapPartyAvailabilityReady) return;
  root._leapPartyAvailabilityReady = true;
  var calendar = root.dataset.leapPartyAvailability === 'calendar';
  var months = [], selected = 0, generation = 0, controller, started = false;
  var monthSelect = root.querySelector('select');
  var refreshButton=root.querySelector('[data-party-refresh]');
  monthSelect.disabled=true;if(refreshButton)refreshButton.disabled=true;
  var status = root.querySelector('[data-party-status]');
  var output = root.querySelector('[data-party-dates]');
  var detail = root.querySelector('[data-party-detail]');
  var fmt = new Intl.DateTimeFormat('en-CA', {timeZone:'America/Toronto',year:'numeric',month:'2-digit',day:'2-digit'});
  function dayKey(seconds) { return fmt.format(new Date(Number(seconds) * 1000)); }
  function state(e, now) {
    if (e.spots_dropin === null || e.spots_dropin === undefined || e.spots_dropin === '' || !Number.isFinite(Number(e.spots_dropin))) return 'Check availability';
    if (Number(e.spots_dropin) <= 0) return 'Full';
    if (Number(e.event_start_time) <= now) return 'Past';
    if (Number(e.registration_start_time) > now || Number(e.program_registration_start_time) > now) return 'Not yet open';
    if ((Number(e.registration_cutoff) > 0 && now >= Number(e.registration_cutoff)) ||
        (Number(e.program_registration_cutoff) > 0 && now >= Number(e.program_registration_cutoff)) ||
        now >= Number(e.event_start_time) - 7 * 86400) return 'Booking closed';
    return 'Available';
  }
  function element(tag, text, cls) {
    var el = document.createElement(tag); if (text !== undefined) el.textContent = text;
    if (cls) el.className = cls; return el;
  }
  function link(text, url) { var el=element('a',text,'lp-book');el.href=url;el.target='_top';return el; }
  function dateLabel(e) { return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',weekday:'long',month:'long',day:'numeric'}).format(new Date(Number(e.event_start_time)*1000)); }
  function timeLabel(e) { return new Intl.DateTimeFormat('en-CA',{timeZone:'America/Toronto',hour:'numeric',minute:'2-digit'}).format(new Date(Number(e.event_start_time)*1000)); }
  function render(events, month) {
    var now=Date.now()/1000, seen=new Set();
    events=events.filter(function(e){var key=String(e.event_id||e.id);if(e.sku!==month.sku||Number(e.program_id)!==month.id||dayKey(e.event_start_time).slice(0,7)!==month.key||seen.has(key))return false;seen.add(key);return true;}).sort(function(a,b){return a.event_start_time-b.event_start_time;});
    output.replaceChildren(); detail.replaceChildren();
    if (!calendar) {
      var list=element('ul',undefined,'lp-date-list');
      events.filter(function(e){return Number(e.event_start_time)>now;}).forEach(function(e){
        var label=state(e,now),li=element('li'),copy=element('span');copy.append(element('strong',dateLabel(e)),element('small',timeLabel(e)));
        li.append(copy,label==='Available'?link('Available / Book',month.url):element('span',label,'lp-status '+(label==='Full'?'lp-full':'')));list.append(li);
      });output.append(list);
    } else {
      var grid=element('div',undefined,'lp-month-grid');
      ['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].forEach(function(d){grid.append(element('span',d,'lp-weekday'));});
      var parts=month.key.split('-').map(Number),offset=new Date(Date.UTC(parts[0],parts[1]-1,1)).getUTCDay(),count=new Date(Date.UTC(parts[0],parts[1],0)).getUTCDate();
      for(var n=0;n<offset;n++)grid.append(element('span'));
      for(var d=1;d<=count;d++){
        var key=month.key+'-'+String(d).padStart(2,'0'),dayEvents=events.filter(function(e){return dayKey(e.event_start_time)===key;});
        var open=dayEvents.filter(function(e){return state(e,now)==='Available';}),label=open.length?'Available':dayEvents.length?state(dayEvents[0],now):'Not offered';
        var cell=element(open.length?'button':'span',undefined,'lp-day '+(open.length?'lp-open':label==='Full'?'lp-full':'lp-unavailable'));
        cell.append(element('strong',String(d)),element('small',label==='Available'?'Open':label==='Full'?'Full':dayEvents.length?'Closed':'—'));
        cell.setAttribute('aria-label',key+', '+label);
        if(open.length){cell.type='button';cell.addEventListener('click',(function(es){return function(){detail.replaceChildren();es.forEach(function(e){var line=element('div',undefined,'lp-selection');line.append(element('p',dateLabel(e)+' at '+timeLabel(e)),link('Book this date',month.url));detail.append(line);});detail.append(element('small','Choose this date on the registration page. Availability is confirmed at checkout.'));};})(open));}
        grid.append(cell);
      }output.append(grid);
    }
    var available=events.filter(function(e){return state(e,now)==='Available';}).length;
    status.textContent=available?available+' available party date'+(available===1?'':'s')+'. Updated from registration.':'No available party dates this month. Try another month.';
    if(!calendar && !output.querySelector('li')) output.append(element('p','No upcoming party dates listed for this month.'));
    return available;
  }
  async function load() {
    if(!months.length)return; var seq=++generation,month=months[selected];
    if(controller)controller.abort();controller=new AbortController();
    status.textContent='Checking live availability…';output.replaceChildren();detail.replaceChildren();root.setAttribute('aria-busy','true');
    var timer=setTimeout(function(){controller.abort();},15000);
    try {
      var productResponse=await fetch(month.url+'?priceDisplayMode=total',{credentials:'omit',cache:'no-store',signal:controller.signal,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});
      if(!productResponse.ok)throw Error('Program unavailable');
      var product=(await productResponse.json()).product;
      if(!product||product.status!=='Public'||Number(product.deleted)||Number(product.program_id)!==month.id||product.sku!==month.sku)throw Error('Program unpublished');
      var parts=month.key.split('-').map(Number),url=new URL('/calendar/',location.origin);
      url.searchParams.set('action','FetchCalendarData');url.searchParams.set('calendarAction','fetchEvents');url.searchParams.append('program[]',String(month.id));
      url.searchParams.set('show_hidden','true');
      var body=new URLSearchParams({start:String(Date.UTC(parts[0],parts[1]-1,1)/1000-86400),end:String(Date.UTC(parts[0],parts[1],1)/1000+86400)});
      var response=await fetch(url.href,{method:'POST',credentials:'omit',cache:'no-store',signal:controller.signal,headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest','Content-Type':'application/x-www-form-urlencoded; charset=UTF-8'},body:body.toString()});
      if(!response.ok)throw Error('Feed unavailable');var data=await response.json();if(!Array.isArray(data))throw Error('Invalid feed');
      if(seq===generation)return render(data,month);
    }catch(e){if(seq===generation){status.textContent='Live availability is temporarily unavailable.';output.replaceChildren(link('Check dates on registration',month.url));}}
    finally{clearTimeout(timer);if(seq===generation)root.removeAttribute('aria-busy');}
  }
  async function catalog(){
      var oldKey=months[selected]&&months[selected].key;
      var r=await fetch('/registration/?_party_dates='+Date.now(),{credentials:'omit',cache:'no-store'});if(!r.ok)throw Error();var doc=new DOMParser().parseFromString(await r.text(),'text/html');
      var today=fmt.format(new Date()).slice(0,7),seen=new Set();
      var candidates=[];
      doc.querySelectorAll('#birthday-party-booking-months a[data-program-id]').forEach(function(a){var u=new URL(a.getAttribute('href'),location.origin),match=u.pathname.match(/\/registration\/product-detail\/(BDAY-(\d{4}-\d{2}))\/?$/);if(!match||u.origin!==location.origin||match[2]<today||seen.has(match[1]))return;seen.add(match[1]);candidates.push({sku:match[1],key:match[2],id:Number(a.dataset.programId),url:u.pathname});});
      if(!candidates.length)throw Error();
      var checked=await Promise.all(candidates.map(async function(m){try{var response=await fetch(m.url+'?priceDisplayMode=total',{credentials:'omit',cache:'no-store',headers:{Accept:'application/json','X-Requested-With':'XMLHttpRequest'}});if(!response.ok)return null;var p=(await response.json()).product;return p&&p.status==='Public'&&!Number(p.deleted)&&Number(p.program_id)===m.id&&p.sku===m.sku?m:null;}catch(e){return null;}}));
      months=checked.filter(Boolean).sort(function(a,b){return a.key.localeCompare(b.key);});if(!months.length)throw Error();
      selected=Math.max(0,months.findIndex(function(m){return m.key===oldKey;}));monthSelect.replaceChildren();
      months.forEach(function(m,i){var label=new Intl.DateTimeFormat('en-CA',{timeZone:'UTC',month:'long',year:'numeric'}).format(new Date(m.key+'-15T12:00:00Z'));var o=element('option',label);o.value=String(i);monthSelect.append(o);});monthSelect.disabled=false;
      monthSelect.value=String(selected);
  }
  async function init(){
    if(started)return;started=true;
    try{
      await catalog();
      monthSelect.disabled=true;
      var available=await load();
      while(available===0&&selected<months.length-1){selected++;monthSelect.value=String(selected);available=await load();}
      monthSelect.disabled=false;if(refreshButton)refreshButton.disabled=false;
      monthSelect.addEventListener('change',function(){selected=Number(monthSelect.value);load();});refreshButton.addEventListener('click',load);
      setInterval(async function(){var rect=root.getBoundingClientRect();if(!document.hidden&&rect.bottom>0&&rect.top<innerHeight){try{await catalog();await load();}catch(e){status.textContent='Live availability is temporarily unavailable. Please check registration.';output.replaceChildren();detail.replaceChildren();}}},60000);
    }catch(e){status.textContent='Please check party dates on registration.';if(refreshButton){refreshButton.disabled=false;refreshButton.onclick=function(){started=false;init();};}}
  }
  if('IntersectionObserver' in window){var observer=new IntersectionObserver(function(entries){if(entries.some(function(e){return e.isIntersecting;})){observer.disconnect();init();}},{rootMargin:'200px'});observer.observe(root);}else init();
}
